head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > getFrameId]<br/>현재 화면을 감싸고 있는 WFrame 객체의 ID 를 반환합니다.",
    "validation" : [
        "현재 화면을 감싸고 있는 WFrame 객체의 런타임 ID 를 반환해야 합니다.",
        "반환되는 ID 는 런타임에 동적으로 생성된 ID 이므로 화면에서 정의한 ID 와 다를 수 있습니다.",
        "WFrame 내부가 아닌 전역 스크립트에서 호출하면 null 을 반환해야 합니다. (※ unitTest 환경에서는 최상위 WFrame(mf)이 존재하여 null 검증 불가)",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_getFrameId_main_onclick = function () {
    var frameId = $p.getFrameId();

    if (frameId !== null) {
        wf_body_bottom.getObj("scwin").setReturnValue("getFrameId() : " + frameId + " (최상위 WFrame)");
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("getFrameId() : null (WFrame 내부가 아님)");
    }
}



scwin.btn_getFrameId_wframe_onclick = function () {
    var frameId = wf_test.getObj("$p").getFrameId();

    if (frameId !== null) {
        var frame = $p.getComponentById(frameId);
        var originalId = frame ? frame.getOriginalID() : "N/A";

        wf_body_bottom.getObj("scwin").setReturnValue("wf_test 내부 getFrameId() : " + frameId);
        wf_body_bottom.getObj("scwin").setReturnValue("  getOriginalID() : " + originalId);
        wf_body_bottom.getObj("scwin").setReturnValue("  getUserData('userData1') : " + (frame ? frame.getUserData("userData1") : "N/A"));
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("wf_test 내부 getFrameId() : null");
    }
}
